\label{prop:parameters}
The two triples
\begin{equation}\label{eq:stage-zero}
 \kappa_0=\frac34,\qquad
 b_0=\frac{173}{2000},\qquad
 \ell_0=\frac{10027}{60000}.
\end{equation}
and
\begin{equation}\label{eq:stage-one}
 \kappa_1=\frac{29991}{40000},\qquad
 b_1=\frac{17307}{200000},\qquad
 \ell_1=\frac{1253399}{7500000}.
\end{equation}
are admissible in the sense of Section~\ref{sec:high}
with the respective margins
\[
 \begin{array}{c|ccc}
 j&g_j&\zeta_j&g_{*,j}\\ \hline
 0&10^{-6}&10^{-7}&1/2000000\\
 1&10^{-7}&10^{-9}&1/20000000.
 \end{array}
\]
Their boundaries are
\[
 B(\ell_0)=B_0=\frac{69991}{80000},\qquad
 B(\ell_1)=B_1=\frac{8748867}{10000000},
\]
and their licensing identities are
\begin{equation}\label{eq:license}
 \frac{1+\kappa_0}{2}=\frac78,\qquad
 \frac{1+\kappa_1}{2}=B_0.
\end{equation}

\label{lem:principal-remainder}
Suppose \(\beta_*>B(\ell)>87/100\).
Let \(\mathscr P_\eta\) denote the \(u=1\)
term of \eqref{eq:high-identity}, and define
\[
 f_\eta(Z)=\frac1{2\pi i}\int_{(2)}
 Z^{C_b(s)}e^{(s-5/6)^2}
                  \frac{H_\eta(s)}{L_F^S(s,\eta)}\,ds.
\]
Then
\[
 \begin{split}
 \left|\frac{\mathscr P_\eta(Z)}{c_S A_T(Z)}
                       -f_\eta(Z)\right|
 \ll{}&
 Z^{C_b(\beta_*)+(1+h)e-l_y/20+\varepsilon}\\
 &+Z^{C_b(\beta_*)+e-h/600+\varepsilon}
 +Z^{C_b(\beta_*)+e-\mu+\varepsilon}.
 \end{split}
\]
